import * as path from "node:path";
function main(): void {
  const p: any = path;
  console.log(p.matchesGlob("a/b/c.js", "a/**/*.js"), p.matchesGlob("a/b/c.js", "**/*.ts"), p.matchesGlob(".hidden", "*"), p.matchesGlob("a", "a/**"), p.matchesGlob("x.md", "*.{txt,md}"), p.matchesGlob("file1", "file[0-9]"), p.matchesGlob("ab", "@(ab|cd)"));
  console.log(p.posix.matchesGlob("src/x/y.js", "src/**/y.js"), p.win32.matchesGlob("a\\b\\c.js", "a/**/*.js"), p.win32.matchesGlob("a\\b", "a/b"));
  console.log(p._makeLong("/tmp/x"), p.matchesGlob.length, p._makeLong.length);
  const f: any = p.dirname;
  const g: any = p.extname;
  let r = "";
  try { f(); } catch (e: any) { r = e.code; }
  try { g(); } catch (e: any) { r += " " + e.code; }
  console.log(r);
  try { p.matchesGlob(1, "a"); } catch (e: any) { console.log(e.code); }
}
